import * as THREE from "three";

const TAU = Math.PI * 2;

function mat(color, options = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: options.roughness ?? 0.66,
    metalness: options.metalness ?? 0,
    emissive: options.emissive ?? 0x000000,
    emissiveIntensity: options.emissiveIntensity ?? 0,
    transparent: options.transparent ?? false,
    opacity: options.opacity ?? 1,
    side: options.side ?? THREE.FrontSide,
    flatShading: options.flatShading ?? false,
  });
}

function physical(color, options = {}) {
  return new THREE.MeshPhysicalMaterial({
    color,
    roughness: options.roughness ?? 0.48,
    metalness: options.metalness ?? 0.04,
    sheen: options.sheen ?? 0.45,
    sheenRoughness: 0.7,
    sheenColor: new THREE.Color(options.sheenColor ?? "#ffffff"),
    clearcoat: options.clearcoat ?? 0,
    clearcoatRoughness: 0.4,
    transparent: options.transparent ?? false,
    opacity: options.opacity ?? 1,
    side: options.side ?? THREE.FrontSide,
  });
}

function capsule(radius, length, material, segments = 12) {
  const mesh = new THREE.Mesh(new THREE.CapsuleGeometry(radius, length, 6, segments), material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function cylinder(rTop, rBottom, height, material, segments = 16) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rTop, rBottom, height, segments), material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function sphere(radius, material, width = 24, height = 18) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, width, height), material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function box(w, h, d, material) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function limb(radiusTop, radiusBottom, length, material, segments = 10) {
  const g = new THREE.CylinderGeometry(radiusTop, radiusBottom, length, segments);
  g.translate(0, -length / 2, 0);
  const mesh = new THREE.Mesh(g, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function makeSkirt({ waist, hem, length, color, trim, sheen = 0.3 }) {
  const group = new THREE.Group();
  const points = [];
  const steps = 10;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const y = -t * length;
    const flare = waist + (hem - waist) * Math.pow(t, 1.55);
    points.push(new THREE.Vector2(flare, y));
  }
  const geo = new THREE.LatheGeometry(points, 40);
  const material = physical(color, { roughness: 0.64, sheen, sheenColor: trim });
  const skirt = new THREE.Mesh(geo, material);
  skirt.castShadow = true;
  skirt.receiveShadow = true;
  skirt.scale.z = 0.8;
  group.add(skirt);

  // Hem shadow and trim
  const trimRing = new THREE.Mesh(
    new THREE.TorusGeometry(hem - 0.012, 0.009, 6, 50),
    mat(trim, { roughness: 0.42, metalness: 0.35 })
  );
  trimRing.rotation.x = Math.PI / 2;
  trimRing.position.y = -length + 0.01;
  trimRing.scale.z = 0.8;
  group.add(trimRing);

  // apron / over-skirt panel
  const panelShape = new THREE.Shape();
  panelShape.moveTo(-waist * 0.7, 0);
  panelShape.lineTo(waist * 0.7, 0);
  panelShape.lineTo(hem * 0.55, -length * 0.94);
  panelShape.quadraticCurveTo(0, -length * 1.02, -hem * 0.55, -length * 0.94);
  panelShape.closePath();
  const panel = new THREE.Mesh(
    new THREE.ShapeGeometry(panelShape, 20),
    physical(trim, { roughness: 0.62, sheen: 0.45, transparent: true, opacity: 0.24, side: THREE.DoubleSide })
  );
  panel.position.set(0, 0.005, waist * 0.78);
  panel.castShadow = false;
  group.add(panel);
  return group;
}

function makeFace(skin, hairColor, eyeColor, lipColor) {
  const group = new THREE.Group();
  const eyeGroups = [];
  const eyeWhiteMat = mat("#f3e7d4", { roughness: 0.35 });
  const irisMat = mat(eyeColor, { roughness: 0.25, emissive: eyeColor, emissiveIntensity: 0.12 });
  const pupilMat = mat("#120b09", { roughness: 0.2 });
  const browMat = mat(hairColor, { roughness: 0.7 });

  for (const side of [-1, 1]) {
    const eye = new THREE.Group();
    eye.position.set(side * 0.057, 0.032, 0.147);
    const white = sphere(0.033, eyeWhiteMat, 16, 12);
    white.scale.set(1, 1.02, 0.45);
    eye.add(white);
    const iris = sphere(0.0145, irisMat, 14, 12);
    iris.position.set(0, 0, 0.015);
    iris.scale.set(1, 1, 0.5);
    eye.add(iris);
    const pupil = sphere(0.0065, pupilMat, 10, 8);
    pupil.position.set(0, 0, 0.021);
    pupil.scale.set(1, 1, 0.35);
    eye.add(pupil);
    const glint = sphere(0.0032, mat("#fff9ef", { emissive: "#fff6e3", emissiveIntensity: 0.8, roughness: 0.1 }), 8, 6);
    glint.position.set(-0.004, 0.005, 0.026);
    eye.add(glint);
    eye.userData.baseScaleY = 1;
    group.add(eye);
    eyeGroups.push(eye);

    const brow = box(0.06, 0.009, 0.012, browMat);
    brow.position.set(side * 0.058, 0.081, 0.146);
    brow.rotation.z = side * 0.09;
    brow.castShadow = false;
    group.add(brow);

    // lashes
    const lash = box(0.064, 0.004, 0.006, mat("#1d100e", { roughness: 0.4 }));
    lash.position.set(side * 0.057, 0.049, 0.169);
    lash.rotation.z = side * 0.05;
    lash.castShadow = false;
    group.add(lash);

    const blush = new THREE.Mesh(
      new THREE.CircleGeometry(0.026, 20),
      new THREE.MeshBasicMaterial({ color: "#be6558", transparent: true, opacity: 0.13, depthWrite: false })
    );
    blush.position.set(side * 0.087, 0.005, 0.143);
    blush.scale.set(1, 0.55, 1);
    group.add(blush);
  }

  const nose = sphere(0.018, skin, 12, 10);
  nose.scale.set(0.6, 0.85, 0.8);
  nose.position.set(0, -0.006, 0.164);
  group.add(nose);

  const mouth = new THREE.Group();
  mouth.position.set(0, -0.064, 0.151);
  const upperLip = sphere(0.032, mat(lipColor, { roughness: 0.4 }), 16, 10);
  upperLip.scale.set(1, 0.24, 0.22);
  upperLip.position.y = 0.003;
  mouth.add(upperLip);
  const lowerLip = sphere(0.028, mat(lipColor, { roughness: 0.36 }), 16, 10);
  lowerLip.scale.set(1, 0.3, 0.3);
  lowerLip.position.y = -0.009;
  mouth.add(lowerLip);
  group.add(mouth);

  const chin = sphere(0.036, skin, 12, 10);
  chin.scale.set(1, 0.55, 0.7);
  chin.position.set(0, -0.113, 0.128);
  group.add(chin);

  return { group, eyeGroups, browMat, mouth, upperLip, lowerLip };
}

function addHair(character, style, hair, hairDark, hairLight, head) {
  const capMat = physical(hair, { roughness: 0.52, sheen: 0.75, sheenColor: hairLight });
  const darkMat = physical(hairDark, { roughness: 0.6, sheen: 0.5, sheenColor: hair });
  const lightMat = physical(hairLight, { roughness: 0.45, sheen: 0.7, sheenColor: hairLight });

  const back = sphere(0.17, capMat, 26, 22);
  back.scale.set(1.04, 1.12, 1.0);
  back.position.set(0, 0.018, -0.026);
  head.add(back);

  const crown = sphere(0.13, capMat, 20, 18);
  crown.scale.set(1.2, 0.7, 1.1);
  crown.position.set(0, 0.135, -0.01);
  head.add(crown);

  const sideLocks = [];
  for (const side of [-1, 1]) {
    const lock = capsule(0.045, 0.16, capMat, 10);
    lock.scale.set(0.7, 1, 0.62);
    lock.position.set(side * 0.145, -0.01, -0.005);
    lock.rotation.z = side * -0.2;
    head.add(lock);
    sideLocks.push(lock);

    const fringe = sphere(0.07, lightMat, 16, 12);
    fringe.scale.set(0.9, 0.6, 0.5);
    fringe.position.set(side * 0.05, 0.115, 0.122);
    fringe.rotation.z = side * -0.4;
    head.add(fringe);
  }

  if (style === "clem") {
    // Voluminous auburn updo and ringlets
    const bun = sphere(0.105, capMat, 20, 16);
    bun.scale.set(1.1, 0.9, 1.0);
    bun.position.set(0, 0.105, -0.14);
    head.add(bun);
    const bunTop = sphere(0.078, lightMat, 18, 14);
    bunTop.scale.set(1, 0.82, 0.95);
    bunTop.position.set(0.02, 0.17, -0.09);
    head.add(bunTop);

    for (let i = 0; i < 5; i++) {
      const a = -0.8 + i * 0.4;
      const curl = new THREE.Mesh(
        new THREE.TorusGeometry(0.045 + (i % 2) * 0.012, 0.018, 6, 16, Math.PI * 1.25),
        i % 2 ? darkMat : capMat
      );
      curl.position.set(Math.sin(a) * 0.19, 0.04 - i * 0.035, 0.06 + Math.cos(a) * 0.06);
      curl.rotation.set(0.5, a, 0.6);
      curl.castShadow = true;
      head.add(curl);
    }

    const curl = capsule(0.03, 0.2, capMat, 8);
    curl.scale.set(0.7, 1, 0.65);
    curl.position.set(0.165, -0.1, 0.02);
    curl.rotation.z = 0.1;
    head.add(curl);
  }

  if (style === "ada") {
    // Severe low chignon with a silver streak
    const chignon = sphere(0.09, capMat, 20, 16);
    chignon.scale.set(1.0, 1.1, 0.9);
    chignon.position.set(0, -0.07, -0.17);
    head.add(chignon);
    const pin = cylinder(0.005, 0.005, 0.28, mat("#d2a453", { metalness: 0.9, roughness: 0.28 }), 8);
    pin.rotation.z = Math.PI / 2.35;
    pin.position.set(0.02, 0.005, -0.15);
    head.add(pin);

    const streak = capsule(0.024, 0.18, mat("#d8d1c2", { roughness: 0.42 }), 8);
    streak.scale.set(0.65, 1, 0.5);
    streak.position.set(-0.14, 0.0, 0.055);
    streak.rotation.z = -0.16;
    head.add(streak);

    const fringe = sphere(0.075, capMat, 16, 12);
    fringe.scale.set(1.2, 0.34, 0.5);
    fringe.position.set(0.02, 0.13, 0.1);
    fringe.rotation.z = -0.25;
    head.add(fringe);
  }

  if (style === "rosa") {
    // Long loose waves
    const backMass = sphere(0.17, capMat, 24, 20);
    backMass.scale.set(1.12, 1.5, 0.9);
    backMass.position.set(0, -0.16, -0.1);
    head.add(backMass);

    for (let i = 0; i < 9; i++) {
      const side = i % 2 === 0 ? -1 : 1;
      const wave = new THREE.Mesh(
        new THREE.TorusGeometry(0.055 + (i % 3) * 0.013, 0.022, 6, 14, Math.PI * 1.4),
        i % 3 === 0 ? lightMat : i % 2 === 0 ? capMat : darkMat
      );
      wave.position.set(side * (0.12 + (i % 3) * 0.022), -0.05 - i * 0.045, -0.1 + (i % 2) * 0.05);
      wave.rotation.set(0.2 + i * 0.1, side * 0.5, 0.7);
      wave.castShadow = true;
      head.add(wave);
    }

    const frontWave = capsule(0.035, 0.25, capMat, 8);
    frontWave.scale.set(0.75, 1, 0.65);
    frontWave.position.set(-0.135, -0.12, 0.11);
    frontWave.rotation.z = -0.1;
    head.add(frontWave);
  }

  return { sideLocks };
}

function addHat(head, style, colors) {
  const group = new THREE.Group();
  const felt = physical(colors.hat, { roughness: 0.72, sheen: 0.35, sheenColor: colors.band });
  const brim = cylinder(0.34, 0.355, 0.018, felt, 32);
  brim.scale.z = 0.88;
  brim.position.y = 0.21;
  brim.rotation.z = style === "rosa" ? 0.05 : 0.02;
  group.add(brim);

  // Slight upturn at the sides
  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.345, 0.01, 6, 48), felt);
  rim.rotation.x = Math.PI / 2;
  rim.scale.z = 0.88;
  rim.position.y = 0.218;
  group.add(rim);

  const crown = cylinder(0.145, 0.185, 0.17, felt, 24);
  crown.position.y = 0.295;
  group.add(crown);

  const dent = new THREE.Mesh(new THREE.SphereGeometry(0.11, 18, 12, 0, TAU, 0, Math.PI / 2.1), felt);
  dent.scale.set(1.1, 0.6, 0.9);
  dent.position.set(0, 0.37, 0.02);
  dent.rotation.x = Math.PI;
  group.add(dent);

  const band = cylinder(0.188, 0.19, 0.035, mat(colors.band, { metalness: 0.55, roughness: 0.36 }), 24);
  band.position.y = 0.235;
  group.add(band);

  if (style === "rosa") {
    const concha = cylinder(0.023, 0.023, 0.012, mat("#c7c3b7", { metalness: 0.8, roughness: 0.32 }), 12);
    concha.rotation.x = Math.PI / 2;
    concha.position.set(0, 0.245, 0.19);
    group.add(concha);
  }

  head.add(group);
  return group;
}

export function createCharacter(id) {
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const palettes = {
    clem: {
      skin: "#e8b89d",
      skinShade: "#cf957c",
      hair: "#8e3a23",
      hairDark: "#5c2114",
      hairLight: "#c66a42",
      dress: "#6d202b",
      dressDark: "#451018",
      trim: "#c49a50",
      hat: "#2a1d19",
      band: "#b8893f",
      lips: "#9d3f3d",
      eye: "#6b3b24",
      metal: "#d2a453",
      accent: "#d2644c",
    },
    ada: {
      skin: "#efcbb1",
      skinShade: "#d8ab90",
      hair: "#2b201f",
      hairDark: "#170f0f",
      hairLight: "#6b5550",
      dress: "#1d4446",
      dressDark: "#10292b",
      trim: "#b8cec4",
      hat: "#1a2b2c",
      band: "#9ebbb2",
      lips: "#8b4a4e",
      eye: "#467a70",
      metal: "#c9b06d",
      accent: "#70a9a0",
    },
    rosa: {
      skin: "#c98763",
      skinShade: "#a96b4c",
      hair: "#2a1714",
      hairDark: "#160b09",
      hairLight: "#6d3c2c",
      dress: "#9c3c2f",
      dressDark: "#632118",
      trim: "#c9a052",
      hat: "#4a3326",
      band: "#3aa99d",
      lips: "#8e3435",
      eye: "#4a2b1c",
      metal: "#d4a64c",
      accent: "#d8a14d",
    },
  };
  const p = palettes[id];

  const skin = physical(p.skin, { roughness: 0.54, sheen: 0.22 });
  const skinShade = mat(p.skinShade, { roughness: 0.58 });
  const hairMat = physical(p.hair, { roughness: 0.52, sheen: 0.6 });
  const dressMat = physical(p.dress, { roughness: 0.64, sheen: 0.5, sheenColor: p.trim });
  const dressDarkMat = physical(p.dressDark, { roughness: 0.7, sheen: 0.35 });
  const trimMat = mat(p.trim, { roughness: 0.4, metalness: 0.3 });
  const leather = mat("#3a2419", { roughness: 0.74 });
  const bootMat = mat("#21140f", { roughness: 0.62 });
  const metal = mat(p.metal, { metalness: 0.78, roughness: 0.3 });

  // Lower body
  const legs = new THREE.Group();
  legs.position.y = 0.92;
  body.add(legs);

  for (const side of [-1, 1]) {
    const leg = new THREE.Group();
    leg.position.set(side * 0.095, 0, 0);
    const upper = limb(0.068, 0.055, 0.42, id === "rosa" ? mat("#31343a", { roughness: 0.8 }) : mat(p.skinShade, { roughness: 0.6 }));
    upper.rotation.z = side * -0.025;
    leg.add(upper);
    const knee = new THREE.Group();
    knee.position.y = -0.42;
    leg.add(knee);
    const lower = limb(0.052, 0.042, 0.39, id === "rosa" ? mat("#31343a", { roughness: 0.8 }) : mat(p.skinShade, { roughness: 0.6 }));
    knee.add(lower);
    const boot = new THREE.Group();
    boot.position.y = -0.37;
    const shaft = cylinder(0.058, 0.052, 0.18, bootMat, 12);
    shaft.position.y = 0.07;
    boot.add(shaft);
    const foot = box(0.095, 0.06, 0.17, bootMat);
    foot.position.set(0, -0.015, 0.04);
    boot.add(foot);
    const toe = sphere(0.047, bootMat, 12, 8);
    toe.scale.set(1, 0.6, 1.3);
    toe.position.set(0, -0.02, 0.12);
    boot.add(toe);
    const heel = box(0.05, 0.045, 0.045, bootMat);
    heel.position.set(0, -0.04, -0.035);
    boot.add(heel);
    knee.add(boot);
    legs.add(leg);
  }

  if (id === "rosa") {
    const pantsWaist = cylinder(0.185, 0.165, 0.09, mat("#31343a", { roughness: 0.8 }), 20);
    pantsWaist.position.y = 0.96;
    body.add(pantsWaist);
  } else {
    const skirtLength = id === "clem" ? 0.93 : 0.9;
    const skirt = makeSkirt({
      waist: 0.175,
      hem: id === "clem" ? 0.43 : 0.35,
      length: skirtLength,
      color: p.dress,
      trim: p.trim,
      sheen: 0.55,
    });
    skirt.position.y = 0.94;
    body.add(skirt);

    if (id === "clem") {
      const bustle = sphere(0.2, dressDarkMat, 20, 16);
      bustle.scale.set(1.1, 0.7, 0.8);
      bustle.position.set(0, 0.82, -0.17);
      body.add(bustle);
      const sash = new THREE.Mesh(new THREE.TorusGeometry(0.205, 0.018, 6, 36), trimMat);
      sash.rotation.x = Math.PI / 2;
      sash.position.y = 0.96;
      sash.scale.z = 0.8;
      body.add(sash);
    } else {
      const apron = new THREE.Mesh(
        new THREE.CylinderGeometry(0.23, 0.31, 0.78, 24, 1, true, -1.15, 2.3),
        physical("#e3d8bd", { roughness: 0.78, sheen: 0.25, transparent: true, opacity: 0.94, side: THREE.DoubleSide })
      );
      apron.position.set(0, 0.54, 0.065);
      apron.scale.z = 0.82;
      body.add(apron);
    }
  }

  // Torso
  const torso = new THREE.Group();
  torso.position.y = 0.92;
  body.add(torso);

  const torsoPoints = [
    new THREE.Vector2(0.155, 0.0),
    new THREE.Vector2(0.145, 0.11),
    new THREE.Vector2(0.165, 0.27),
    new THREE.Vector2(0.205, 0.39),
    new THREE.Vector2(0.235, 0.46),
    new THREE.Vector2(0.215, 0.5),
    new THREE.Vector2(0.14, 0.53),
  ];
  const torsoGeo = new THREE.LatheGeometry(torsoPoints, 32);
  const torsoMesh = new THREE.Mesh(torsoGeo, id === "rosa" ? mat(p.dress, { roughness: 0.78 }) : dressMat);
  torsoMesh.scale.z = 0.68;
  torsoMesh.castShadow = true;
  torsoMesh.receiveShadow = true;
  torso.add(torsoMesh);

  // neckline / blouse details
  if (id === "clem") {
    const corset = new THREE.Mesh(
      new THREE.CylinderGeometry(0.162, 0.185, 0.32, 24, 1, true),
      physical("#3a1018", { roughness: 0.58, sheen: 0.55, sheenColor: p.trim })
    );
    corset.scale.z = 0.72;
    corset.position.y = 0.2;
    torso.add(corset);

    for (let i = -2; i <= 2; i++) {
      const bone = box(0.012, 0.3, 0.03, mat(p.trim, { metalness: 0.45, roughness: 0.44 }));
      bone.position.set(i * 0.052, 0.2, 0.13);
      torso.add(bone);
    }

    const neckline = new THREE.Mesh(
      new THREE.TorusGeometry(0.115, 0.013, 8, 28, Math.PI),
      trimMat
    );
    neckline.rotation.set(Math.PI / 2, 0, Math.PI);
    neckline.position.set(0, 0.49, 0.036);
    neckline.scale.z = 0.7;
    torso.add(neckline);
  }

  if (id === "ada") {
    const collar = new THREE.Mesh(
      new THREE.CylinderGeometry(0.095, 0.11, 0.045, 20),
      physical("#e5dbc5", { roughness: 0.75, sheen: 0.3 })
    );
    collar.position.y = 0.515;
    torso.add(collar);
    const cameo = new THREE.Mesh(new THREE.CircleGeometry(0.035, 22), mat("#c9b06d", { metalness: 0.5, roughness: 0.32 }));
    cameo.position.set(0, 0.435, 0.152);
    torso.add(cameo);
    const cameoInner = new THREE.Mesh(new THREE.CircleGeometry(0.025, 22), mat("#d8cfbb", { roughness: 0.4 }));
    cameoInner.position.set(0, 0.435, 0.154);
    torso.add(cameoInner);
    const buttons = [];
    for (let i = 0; i < 5; i++) {
      const button = sphere(0.009, trimMat, 8, 6);
      button.position.set(0, 0.38 - i * 0.07, 0.145 - i * 0.007);
      torso.add(button);
      buttons.push(button);
    }
  }

  if (id === "rosa") {
    const shirt = new THREE.Mesh(
      new THREE.CylinderGeometry(0.19, 0.18, 0.35, 24, 1, true),
      physical(p.dress, { roughness: 0.72, sheen: 0.4 })
    );
    shirt.scale.z = 0.68;
    shirt.position.y = 0.3;
    torso.add(shirt);

    const vest = new THREE.Mesh(
      new THREE.CylinderGeometry(0.203, 0.19, 0.38, 24, 1, true),
      physical("#4a2d20", { roughness: 0.7, sheen: 0.3 })
    );
    vest.scale.z = 0.71;
    vest.position.y = 0.28;
    torso.add(vest);

    const vShape = new THREE.Shape();
    vShape.moveTo(-0.12, 0.48);
    vShape.lineTo(0.12, 0.48);
    vShape.lineTo(0.06, 0.23);
    vShape.lineTo(0, 0.12);
    vShape.lineTo(-0.06, 0.23);
    vShape.closePath();
    const vPanel = new THREE.Mesh(
      new THREE.ShapeGeometry(vShape),
      mat(p.dress, { side: THREE.DoubleSide })
    );
    vPanel.position.set(0, 0.02, 0.148);
    torso.add(vPanel);

    const necklace = new THREE.Mesh(new THREE.TorusGeometry(0.075, 0.007, 6, 20, Math.PI), mat("#3aa99d", { metalness: 0.4, roughness: 0.4 }));
    necklace.rotation.set(Math.PI / 2, 0, Math.PI);
    necklace.position.set(0, 0.47, 0.055);
    necklace.scale.z = 0.7;
    torso.add(necklace);
    const pendant = sphere(0.016, mat("#3aa99d", { roughness: 0.38, metalness: 0.25 }), 12, 10);
    pendant.position.set(0, 0.39, 0.145);
    torso.add(pendant);
  }

  // Arms
  const armGroups = [];
  const hands = [];
  for (const side of [-1, 1]) {
    const shoulder = new THREE.Group();
    shoulder.position.set(side * 0.225, 0.445, 0);
    torso.add(shoulder);
    const shoulderCap = sphere(0.067, id === "rosa" ? mat(p.dress, { roughness: 0.75 }) : dressMat, 14, 12);
    shoulderCap.scale.set(1, 0.9, 0.9);
    shoulder.add(shoulderCap);

    const upper = limb(0.054, 0.045, 0.27, id === "rosa" ? mat(p.dress, { roughness: 0.75 }) : dressMat);
    upper.rotation.z = side * 0.04;
    shoulder.add(upper);

    const elbow = new THREE.Group();
    elbow.position.y = -0.27;
    shoulder.add(elbow);

    const lower = limb(0.043, 0.033, 0.25, id === "clem" ? mat(p.skin, { roughness: 0.58 }) : id === "ada" ? mat("#d9d0bd", { roughness: 0.7 }) : mat(p.skin, { roughness: 0.58 }));
    elbow.add(lower);

    if (id === "clem") {
      const bangle = new THREE.Mesh(new THREE.TorusGeometry(0.04, 0.008, 6, 14), metal);
      bangle.rotation.x = Math.PI / 2;
      bangle.position.y = -0.2;
      elbow.add(bangle);
    }

    const hand = new THREE.Group();
    hand.position.y = -0.255;
    const palm = sphere(0.045, skin, 14, 12);
    palm.scale.set(0.8, 1.1, 0.55);
    hand.add(palm);
    for (let f = 0; f < 4; f++) {
      const finger = capsule(0.0095, 0.035, skin, 6);
      finger.position.set((f - 1.5) * 0.017, -0.035, 0.005);
      finger.rotation.x = 0.1;
      hand.add(finger);
    }
    const thumb = capsule(0.011, 0.027, skin, 6);
    thumb.position.set(side * 0.037, -0.012, 0.008);
    thumb.rotation.z = side * 0.65;
    hand.add(thumb);
    elbow.add(hand);
    armGroups.push({ side, shoulder, elbow, hand });
    hands.push(hand);
  }

  // Poses
  const [leftArm, rightArm] = armGroups; // side -1 then +1
  if (id === "clem") {
    leftArm.shoulder.rotation.set(0.1, 0, -0.38);
    leftArm.elbow.rotation.set(0.05, 0.2, -1.28);
    leftArm.hand.rotation.z = -0.3;
    rightArm.shoulder.rotation.set(-0.12, 0, 0.22);
    rightArm.elbow.rotation.set(-0.35, 0, 0.16);
    rightArm.hand.rotation.x = -0.2;
  } else if (id === "ada") {
    leftArm.shoulder.rotation.set(-0.24, 0.05, -0.18);
    leftArm.elbow.rotation.set(-0.78, 0.2, -0.28);
    leftArm.hand.rotation.set(-0.2, 0, -0.2);
    rightArm.shoulder.rotation.set(-0.24, -0.05, 0.18);
    rightArm.elbow.rotation.set(-0.78, -0.2, 0.28);
    rightArm.hand.rotation.set(-0.2, 0, 0.2);
  } else {
    leftArm.shoulder.rotation.set(-0.06, 0, -0.14);
    leftArm.elbow.rotation.set(-0.18, 0, -0.1);
    rightArm.shoulder.rotation.set(0.1, 0, 0.36);
    rightArm.elbow.rotation.set(-0.5, 0, 0.9);
    rightArm.hand.rotation.z = 0.2;
  }

  // Head
  const neck = cylinder(0.052, 0.06, 0.12, skin, 14);
  neck.position.y = 1.46;
  body.add(neck);

  const head = new THREE.Group();
  head.position.y = 1.62;
  body.add(head);

  const skull = sphere(0.158, skin, 32, 26);
  skull.scale.set(0.98, 1.13, 0.94);
  head.add(skull);

  const jaw = sphere(0.115, skin, 20, 16);
  jaw.scale.set(0.9, 0.68, 0.82);
  jaw.position.set(0, -0.095, 0.018);
  head.add(jaw);

  for (const side of [-1, 1]) {
    const ear = sphere(0.036, skin, 12, 10);
    ear.scale.set(0.45, 1, 0.6);
    ear.position.set(side * 0.155, 0.005, 0);
    head.add(ear);
    const earring = sphere(0.011, metal, 10, 8);
    earring.position.set(side * 0.162, -0.05, 0.005);
    earring.scale.set(1, 1.5, 0.7);
    head.add(earring);
  }

  const face = makeFace(skin, p.hair, p.eye, p.lips);
  face.group.position.set(0, -0.005, 0);
  head.add(face.group);

  const hair = addHair(body, id, p.hair, p.hairDark, p.hairLight, head);

  if (id !== "ada") addHat(head, id, p);
  else {
    // Ada gets a small silver comb instead of a hat
    const comb = new THREE.Group();
    for (let i = 0; i < 5; i++) {
      const tine = box(0.007, 0.075, 0.01, metal);
      tine.position.set((i - 2) * 0.013, 0.1, 0.02);
      tine.rotation.z = (i - 2) * 0.04;
      comb.add(tine);
    }
    comb.position.set(0.11, 0.1, 0.02);
    comb.rotation.z = -0.42;
    head.add(comb);
  }

  // Accessories
  if (id === "clem") {
    const choker = new THREE.Mesh(new THREE.TorusGeometry(0.064, 0.009, 6, 20), mat("#291018", { roughness: 0.5 }));
    choker.rotation.x = Math.PI / 2;
    choker.position.y = 1.505;
    choker.scale.z = 0.7;
    body.add(choker);
    const gem = sphere(0.012, mat("#b52d3f", { emissive: "#6d0d1b", emissiveIntensity: 0.3, roughness: 0.25 }), 10, 8);
    gem.position.set(0, 1.49, 0.062);
    body.add(gem);
  }

  if (id === "ada") {
    // spectacles
    const glasses = new THREE.Group();
    for (const side of [-1, 1]) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.055, 0.0045, 5, 24), mat("#c9b06d", { metalness: 0.75, roughness: 0.32 }));
      ring.position.set(side * 0.058, 0.028, 0.176);
      ring.scale.set(1, 0.9, 1);
      glasses.add(ring);
    }
    const bridge = cylinder(0.003, 0.003, 0.03, mat("#c9b06d", { metalness: 0.8, roughness: 0.3 }), 6);
    bridge.rotation.z = Math.PI / 2;
    bridge.position.set(0, 0.03, 0.176);
    glasses.add(bridge);
    const chain = new THREE.Mesh(new THREE.TorusGeometry(0.06, 0.003, 4, 18, Math.PI * 0.85), mat("#c9b06d", { metalness: 0.8, roughness: 0.3 }));
    chain.position.set(0.12, -0.02, 0.12);
    chain.rotation.z = -0.65;
    glasses.add(chain);
    head.add(glasses);
  }

  if (id === "rosa") {
    // Gun belt and holster
    const belt = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.21, 0.06, 24, 1, true), leather);
    belt.scale.z = 0.78;
    belt.position.y = 0.93;
    body.add(belt);
    const buckle = box(0.055, 0.04, 0.012, metal);
    buckle.position.set(0, 0.93, 0.166);
    body.add(buckle);

    for (let i = 0; i < 6; i++) {
      const bullet = cylinder(0.007, 0.007, 0.025, mat("#c99a46", { metalness: 0.8, roughness: 0.28 }), 8);
      bullet.position.set(-0.13 + i * 0.045, 0.945, 0.162);
      bullet.rotation.z = Math.PI / 2;
      body.add(bullet);
    }

    const holster = box(0.065, 0.17, 0.05, leather);
    holster.position.set(0.205, 0.82, -0.01);
    holster.rotation.z = -0.12;
    body.add(holster);

    const gunGrip = box(0.035, 0.085, 0.025, mat("#4a2c1f", { roughness: 0.6 }));
    gunGrip.position.set(0.218, 0.92, 0.005);
    gunGrip.rotation.z = -0.2;
    body.add(gunGrip);
  }

  root.userData.parts = {
    body,
    torso,
    head,
    face,
    leftArm,
    rightArm,
    hands,
    hair,
  };
  root.userData.id = id;
  root.userData.time = 0;
  root.userData.blinkAt = 2 + Math.random() * 3;
  root.userData.blinkUntil = 0;
  root.userData.mood = "neutral";
  root.userData.speaking = false;
  root.userData.phase = Math.random() * TAU;

  root.userData.setMood = (mood = "neutral") => {
    root.userData.mood = mood;
    const m = mood.toLowerCase();
    const brows = [face.eyeGroups[0], face.eyeGroups[1]];
    // Reset
    face.group.children.forEach((child) => {
      if (child.geometry?.type === "BoxGeometry" && child.position.y > 0.07 && Math.abs(child.position.x) < 0.1) {
        child.rotation.z = Math.sign(child.position.x) * 0.09;
        child.position.y = 0.081;
      }
    });
    face.mouth.rotation.z = 0;
    face.upperLip.scale.set(1, 0.24, 0.22);
    face.lowerLip.scale.set(1, 0.3, 0.3);
    face.mouth.position.y = -0.064;
    face.eyeGroups.forEach((eye) => {
      eye.scale.set(1, 1, 1);
    });

    const browBoxes = face.group.children.filter(
      (child) => child.geometry?.type === "BoxGeometry" && child.position.y > 0.07 && Math.abs(child.position.x) < 0.1
    );

    if (/(soft|tender|warm|love|intimat|smitten|relieved|hopeful|sad|hurt|frightened|afraid|grieving|quiet)/.test(m)) {
      browBoxes.forEach((brow) => {
        brow.rotation.z = Math.sign(brow.position.x) * -0.06;
        brow.position.y = 0.086;
      });
      face.upperLip.scale.set(1.14, 0.3, 0.24);
      face.lowerLip.scale.set(1.08, 0.38, 0.32);
      face.eyeGroups.forEach((eye) => {
        eye.scale.y = 0.9;
      });
    }

    if (/(smil|sly|grin|delight|amuse|confident|hostess|fierce|danger|playful|teasing|predator)/.test(m)) {
      face.mouth.rotation.z = 0.055;
      face.upperLip.scale.set(1.2, 0.28, 0.23);
      face.lowerLip.scale.set(1.06, 0.4, 0.32);
      face.mouth.position.y = -0.061;
      browBoxes.forEach((brow, i) => {
        if (i === 1) {
          brow.rotation.z = -0.14;
          brow.position.y = 0.089;
        }
      });
    }

    if (/(angry|furious|possessive|stern|determined|hard|cold|clinical|professional)/.test(m)) {
      browBoxes.forEach((brow) => {
        brow.rotation.z = Math.sign(brow.position.x) * 0.2;
        brow.position.y = 0.076;
      });
      face.upperLip.scale.set(0.92, 0.22, 0.22);
      face.lowerLip.scale.set(0.88, 0.26, 0.28);
      face.eyeGroups.forEach((eye) => {
        eye.scale.y = 0.94;
      });
    }

    if (/(hurt|sad|grieving|frightened|afraid|wound|sorry)/.test(m)) {
      browBoxes.forEach((brow) => {
        brow.rotation.z = Math.sign(brow.position.x) * -0.21;
        brow.position.y = 0.083;
      });
      face.upperLip.scale.set(0.95, 0.25, 0.22);
      face.lowerLip.scale.set(0.92, 0.26, 0.26);
      face.mouth.position.y = -0.067;
    }
  };

  root.userData.setSpeaking = (speaking) => {
    root.userData.speaking = speaking;
  };

  root.userData.update = (time, dt) => {
    const parts = root.userData.parts;
    const phase = root.userData.phase;
    const breathing = Math.sin(time * 1.4 + phase) * 0.006;
    parts.torso.position.y = 0.92 + breathing;
    parts.torso.scale.y = 1 + breathing * 1.5;
    parts.body.rotation.z = Math.sin(time * 0.48 + phase) * 0.006;
    parts.body.position.y = Math.sin(time * 0.65 + phase) * 0.004;
    parts.head.rotation.y = Math.sin(time * 0.33 + phase) * 0.035;
    parts.head.rotation.x = Math.sin(time * 0.47 + phase * 1.3) * 0.012;

    if (root.userData.speaking) {
      parts.head.rotation.y += Math.sin(time * 4.2 + phase) * 0.018;
      parts.head.rotation.x += Math.sin(time * 5.5 + phase) * 0.008;
      const jaw = 0.55 + Math.sin(time * 15 + phase) * 0.45;
      parts.face.mouth.scale.y = 0.85 + jaw * 0.35;
      parts.face.lowerLip.position.y = -0.009 - jaw * 0.008;
      parts.face.eyeGroups.forEach((eye) => {
        eye.scale.y *= 0.99 + Math.sin(time * 8) * 0.01;
      });
    } else {
      parts.face.mouth.scale.y += (1 - parts.face.mouth.scale.y) * 0.2;
      parts.face.lowerLip.position.y += (-0.009 - parts.face.lowerLip.position.y) * 0.2;
    }

    if (time > root.userData.blinkAt) {
      root.userData.blinkUntil = time + 0.13;
      root.userData.blinkAt = time + 3.2 + Math.random() * 4.6;
    }
    if (time < root.userData.blinkUntil) {
      parts.face.eyeGroups.forEach((eye) => {
        eye.scale.y = 0.08;
      });
    }

    // subtle arm life
    const gesture = root.userData.speaking ? Math.sin(time * 3.2 + phase) * 0.04 : 0;
    parts.rightArm.shoulder.rotation.x += (gesture - parts.rightArm.shoulder.rotation.x * 0.02) * 0.04;
  };

  return root;
}

import * as THREE from "three";

function canvasTexture(width, height, draw, repeat = [1, 1]) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext("2d");
  draw(ctx, width, height);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(repeat[0], repeat[1]);
  texture.anisotropy = 4;
  return texture;
}

function noise(ctx, width, height, amount, opacity = 0.05) {
  for (let i = 0; i < amount; i++) {
    const x = Math.random() * width;
    const y = Math.random() * height;
    const s = Math.random() * 2 + 0.4;
    ctx.fillStyle = `rgba(${Math.random() > 0.45 ? "255,235,200" : "0,0,0"},${Math.random() * opacity})`;
    ctx.fillRect(x, y, s, s);
  }
}

export function woodTexture(base = "#6b4228", grain = "#3e2518", repeat = [2, 2]) {
  return canvasTexture(
    512,
    512,
    (ctx, w, h) => {
      ctx.fillStyle = base;
      ctx.fillRect(0, 0, w, h);
      for (let i = 0; i < 80; i++) {
        const y = Math.random() * h;
        ctx.strokeStyle = `rgba(${parseInt(grain.slice(1, 3), 16)},${parseInt(grain.slice(3, 5), 16)},${parseInt(grain.slice(5, 7), 16)},${0.08 + Math.random() * 0.24})`;
        ctx.lineWidth = 0.5 + Math.random() * 2.5;
        ctx.beginPath();
        ctx.moveTo(0, y);
        for (let x = 0; x <= w; x += 22) {
          ctx.lineTo(x, y + Math.sin(x * 0.025 + i) * 2.6 + (Math.random() - 0.5) * 1.5);
        }
        ctx.stroke();
      }
      for (let i = 0; i < 8; i++) {
        const x = Math.random() * w;
        const y = Math.random() * h;
        ctx.strokeStyle = "rgba(40,20,10,.35)";
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        ctx.ellipse(x, y, 8 + Math.random() * 10, 3 + Math.random() * 4, Math.random(), 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.fillStyle = "rgba(20,10,5,.1)";
      for (let i = 0; i < 7; i++) ctx.fillRect(0, 0, w, 1);
      noise(ctx, w, h, 2600, 0.09);
    },
    repeat
  );
}

export function plankTexture(base = "#5f3b26", repeat = [3, 3]) {
  return canvasTexture(
    512,
    512,
    (ctx, w, h) => {
      ctx.fillStyle = base;
      ctx.fillRect(0, 0, w, h);
      const plank = 64;
      for (let y = 0; y < h; y += plank) {
        ctx.fillStyle = `rgba(255,235,200,${Math.random() * 0.035})`;
        ctx.fillRect(0, y, w, plank);
        ctx.strokeStyle = "rgba(25,12,8,.55)";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
        for (let i = 0; i < 4; i++) {
          const gy = y + 8 + Math.random() * (plank - 16);
          ctx.strokeStyle = "rgba(40,22,12,.13)";
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(0, gy);
          ctx.bezierCurveTo(w * 0.3, gy + 3, w * 0.6, gy - 3, w, gy + 1);
          ctx.stroke();
        }
        const joint = Math.random() * w;
        ctx.strokeStyle = "rgba(24,12,7,.45)";
        ctx.beginPath();
        ctx.moveTo(joint, y);
        ctx.lineTo(joint, y + plank);
        ctx.stroke();
      }
      noise(ctx, w, h, 2400, 0.08);
    },
    repeat
  );
}

export function wallpaperTexture(base = "#4b1b24", gold = "#b58b4c", repeat = [2, 1]) {
  return canvasTexture(
    512,
    512,
    (ctx, w, h) => {
      ctx.fillStyle = base;
      ctx.fillRect(0, 0, w, h);
      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, "rgba(0,0,0,.08)");
      gradient.addColorStop(0.5, "rgba(255,190,120,.02)");
      gradient.addColorStop(1, "rgba(0,0,0,.12)");
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);

      const step = 64;
      ctx.strokeStyle = gold;
      ctx.globalAlpha = 0.09;
      ctx.lineWidth = 1.2;
      for (let y = 0; y < h + step; y += step) {
        for (let x = 0; x < w + step; x += step) {
          const ox = (Math.floor(y / step) % 2) * (step / 2);
          ctx.beginPath();
          ctx.moveTo(x + ox, y);
          ctx.quadraticCurveTo(x + ox + step / 2, y + step / 2, x + ox, y + step);
          ctx.quadraticCurveTo(x + ox - step / 2, y + step / 2, x + ox, y);
          ctx.stroke();
          ctx.beginPath();
          ctx.arc(x + ox + step / 2, y + step / 2, 4, 0, Math.PI * 2);
          ctx.stroke();
        }
      }
      ctx.globalAlpha = 1;
      noise(ctx, w, h, 1800, 0.06);
    },
    repeat
  );
}

export function dirtTexture(repeat = [10, 10]) {
  return canvasTexture(
    512,
    512,
    (ctx, w, h) => {
      ctx.fillStyle = "#9a7250";
      ctx.fillRect(0, 0, w, h);
      for (let i = 0; i < 2200; i++) {
        const shade = Math.random();
        ctx.fillStyle = shade > 0.6 ? "rgba(219,184,137,.18)" : shade > 0.3 ? "rgba(88,53,32,.18)" : "rgba(149,111,70,.26)";
        const r = Math.random() * 3.5 + 0.5;
        ctx.beginPath();
        ctx.arc(Math.random() * w, Math.random() * h, r, 0, Math.PI * 2);
        ctx.fill();
      }
      for (let i = 0; i < 14; i++) {
        ctx.strokeStyle = "rgba(70,44,29,.12)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        const y = Math.random() * h;
        ctx.moveTo(0, y);
        for (let x = 0; x < w; x += 24) ctx.lineTo(x, y + Math.sin(x * 0.03 + i) * 4);
        ctx.stroke();
      }
    },
    repeat
  );
}

export function rockTexture(repeat = [4, 4]) {
  return canvasTexture(
    512,
    512,
    (ctx, w, h) => {
      ctx.fillStyle = "#5b4435";
      ctx.fillRect(0, 0, w, h);
      for (let i = 0; i < 700; i++) {
        const x = Math.random() * w;
        const y = Math.random() * h;
        const s = Math.random() * 24 + 4;
        ctx.fillStyle = `rgba(${Math.random() > 0.5 ? "120,92,70" : "48,34,27"},${Math.random() * 0.28})`;
        ctx.beginPath();
        ctx.ellipse(x, y, s, s * (0.3 + Math.random() * 0.5), Math.random() * Math.PI, 0, Math.PI * 2);
        ctx.fill();
      }
      for (let i = 0; i < 20; i++) {
        ctx.strokeStyle = "rgba(24,16,13,.3)";
        ctx.lineWidth = 1 + Math.random();
        ctx.beginPath();
        let x = Math.random() * w;
        let y = Math.random() * h;
        ctx.moveTo(x, y);
        for (let j = 0; j < 5; j++) {
          x += (Math.random() - 0.5) * 90;
          y += Math.random() * 50;
          ctx.lineTo(x, y);
        }
        ctx.stroke();
      }
    },
    repeat
  );
}

export function fabricTexture(base = "#5a1b26", repeat = [2, 2]) {
  return canvasTexture(
    256,
    256,
    (ctx, w, h) => {
      ctx.fillStyle = base;
      ctx.fillRect(0, 0, w, h);
      ctx.globalAlpha = 0.12;
      for (let i = 0; i < w; i += 3) {
        ctx.strokeStyle = i % 6 === 0 ? "#fff4dc" : "#1b0708";
        ctx.beginPath();
        ctx.moveTo(i, 0);
        ctx.lineTo(i, h);
        ctx.stroke();
      }
      for (let j = 0; j < h; j += 3) {
        ctx.strokeStyle = j % 6 === 0 ? "#fff4dc" : "#1b0708";
        ctx.beginPath();
        ctx.moveTo(0, j);
        ctx.lineTo(w, j);
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
      noise(ctx, w, h, 700, 0.06);
    },
    repeat
  );
}

export function skyTexture(top = "#1c2140", middle = "#a55545", bottom = "#e8a35e") {
  return canvasTexture(
    16,
    512,
    (ctx, w, h) => {
      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, top);
      gradient.addColorStop(0.5, middle);
      gradient.addColorStop(0.78, bottom);
      gradient.addColorStop(1, "#78543c");
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);
    },
    [1, 1]
  );
}

export function rugTexture() {
  return canvasTexture(
    512,
    256,
    (ctx, w, h) => {
      ctx.fillStyle = "#5a1d1b";
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = "#c19a50";
      ctx.lineWidth = 8;
      ctx.strokeRect(14, 14, w - 28, h - 28);
      ctx.strokeStyle = "#28100e";
      ctx.lineWidth = 3;
      ctx.strokeRect(30, 30, w - 60, h - 60);
      for (let i = 0; i < 8; i++) {
        const cx = 64 + i * 55;
        ctx.save();
        ctx.translate(cx, h / 2);
        ctx.rotate(Math.PI / 4);
        ctx.strokeStyle = i % 2 ? "#c19a50" : "#8d5f2d";
        ctx.lineWidth = 3;
        ctx.strokeRect(-19, -19, 38, 38);
        ctx.restore();
      }
      noise(ctx, w, h, 900, 0.08);
    },
    [1, 1]
  );
}

export function signTexture(title, subtitle = "", options = {}) {
  const w = 512;
  const h = options.tall ? 280 : 160;
  return canvasTexture(
    w,
    h,
    (ctx) => {
      ctx.fillStyle = options.background ?? "#241610";
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = options.border ?? "#c49a50";
      ctx.lineWidth = 6;
      ctx.strokeRect(12, 12, w - 24, h - 24);
      ctx.strokeStyle = "rgba(196,154,80,.35)";
      ctx.lineWidth = 1;
      ctx.strokeRect(24, 24, w - 48, h - 48);
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillStyle = options.color ?? "#e7c985";
      ctx.font = `bold ${options.fontSize ?? 70}px Georgia, serif`;
      ctx.fillText(title, w / 2, subtitle ? h / 2 - 22 : h / 2);
      if (subtitle) {
        ctx.fillStyle = options.subColor ?? "#a98c5b";
        ctx.font = "22px Georgia, serif";
        ctx.fillText(subtitle, w / 2, h / 2 + 44);
      }
      // grain
      for (let i = 0; i < 1000; i++) {
        ctx.fillStyle = `rgba(0,0,0,${Math.random() * 0.13})`;
        ctx.fillRect(Math.random() * w, Math.random() * h, 1.5, 1.5);
      }
    },
    [1, 1]
  );
}

export function posterTexture(kind = "wanted") {
  return canvasTexture(
    256,
    384,
    (ctx, w, h) => {
      ctx.fillStyle = "#d8c7a1";
      ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = "rgba(91,64,36,.12)";
      for (let i = 0; i < 300; i++) ctx.fillRect(Math.random() * w, Math.random() * h, 2, 2);
      ctx.strokeStyle = "#4a2d1c";
      ctx.lineWidth = 4;
      ctx.strokeRect(12, 12, w - 24, h - 24);
      ctx.textAlign = "center";
      ctx.fillStyle = "#3a2114";
      ctx.font = "bold 38px Georgia, serif";
      ctx.fillText(kind === "wanted" ? "WANTED" : "CINDER", w / 2, 60);
      if (kind === "wanted") {
        ctx.fillStyle = "#563a24";
        ctx.beginPath();
        ctx.arc(w / 2, 160, 53, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#d8c7a1";
        ctx.beginPath();
        ctx.arc(w / 2, 158, 39, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#4a2d1c";
        ctx.font = "bold 27px Georgia, serif";
        ctx.fillText("J. CALLOWAY", w / 2, 250);
        ctx.font = "18px Georgia, serif";
        ctx.fillText("$500 REWARD", w / 2, 290);
        ctx.fillText("ALIVE OR ANSWERED FOR", w / 2, 320);
      } else {
        ctx.font = "bold 72px Georgia, serif";
        ctx.fillText("GULCH", w / 2, 180);
        ctx.font = "21px Georgia, serif";
        ctx.fillText("POP. 412", w / 2, 235);
        ctx.fillText("ELEV. 6,204 FT", w / 2, 270);
        ctx.fillText("EST. 1871", w / 2, 305);
      }
    },
    [1, 1]
  );
}

export function windowTexture(glow = "#ffd18a") {
  return canvasTexture(
    256,
    384,
    (ctx, w, h) => {
      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, glow);
      gradient.addColorStop(0.65, "#c96b3d");
      gradient.addColorStop(1, "#68362c");
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = "#2a1a12";
      ctx.lineWidth = 9;
      ctx.beginPath();
      ctx.moveTo(w / 2, 0);
      ctx.lineTo(w / 2, h);
      ctx.moveTo(0, h * 0.45);
      ctx.lineTo(w, h * 0.45);
      ctx.stroke();
      ctx.strokeStyle = "rgba(60,30,18,.5)";
      ctx.lineWidth = 2;
      for (let i = 0; i < 20; i++) {
        ctx.beginPath();
        ctx.moveTo(Math.random() * w, 0);
        ctx.lineTo(Math.random() * w, h);
        ctx.stroke();
      }
      ctx.strokeStyle = "#2a1a12";
      ctx.lineWidth = 15;
      ctx.strokeRect(5, 5, w - 10, h - 10);
    },
    [1, 1]
  );
}

export function starSprite() {
  return canvasTexture(64, 64, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, "rgba(255,238,190,1)");
    g.addColorStop(0.25, "rgba(255,204,120,.75)");
    g.addColorStop(0.6, "rgba(255,160,60,.18)");
    g.addColorStop(1, "rgba(255,140,40,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

export function dustSprite() {
  return canvasTexture(64, 64, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, "rgba(255,232,190,.9)");
    g.addColorStop(0.45, "rgba(241,209,156,.35)");
    g.addColorStop(1, "rgba(241,209,156,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

import * as THREE from "three";
import {
  dirtTexture,
  dustSprite,
  fabricTexture,
  plankTexture,
  posterTexture,
  rockTexture,
  rugTexture,
  signTexture,
  skyTexture,
  starSprite,
  wallpaperTexture,
  windowTexture,
  woodTexture,
} from "./textures.js";

const TAU = Math.PI * 2;

const TEX = {};
function textures() {
  if (TEX.ready) return TEX;
  TEX.wood = woodTexture("#6b4228", "#3a2014", [3, 2]);
  TEX.woodDark = woodTexture("#49301f", "#28150e", [2, 2]);
  TEX.plank = plankTexture("#5b3925", [5, 5]);
  TEX.wallpaper = wallpaperTexture("#4d1b24", "#b58b4c", [2, 1]);
  TEX.wallpaperGreen = wallpaperTexture("#233b35", "#9bb8a1", [2, 1]);
  TEX.dirt = dirtTexture([12, 12]);
  TEX.rock = rockTexture([5, 5]);
  TEX.rug = rugTexture();
  TEX.fabric = fabricTexture("#5a1b26", [2, 2]);
  TEX.dust = dustSprite();
  TEX.star = starSprite();
  TEX.window = windowTexture();
  TEX.skyDusk = skyTexture("#171a38", "#a24f46", "#f0aa5f");
  TEX.skyDawn = skyTexture("#1c2f4c", "#c47d72", "#f6cf95");
  TEX.wanted = posterTexture("wanted");
  TEX.town = posterTexture("town");
  TEX.saloonSign = signTexture("GILDED LILY", "ROOMS · WHISKEY · LUCK", { fontSize: 62 });
  TEX.clinicSign = signTexture("HALE'S CLINIC", "PHYSICIAN & SURGEON", { fontSize: 54, background: "#1d302c", border: "#a9c2b7", color: "#dce8da", subColor: "#93a893" });
  TEX.assaySign = signTexture("ASSAY OFFICE", "CINDER MINING CO.", { fontSize: 48, background: "#2e2319", border: "#b78f4c", color: "#e0c48c", subColor: "#9e8152" });
  TEX.stableSign = signTexture("DELGADO STABLES", "HORSES · FREIGHT · NO QUESTIONS", { fontSize: 45, background: "#3a271b", border: "#b68c4b", color: "#e1c386", subColor: "#9d7c4d" });
  TEX.mineSign = signTexture("CINDER MINE", "NO TRESPASSING · KEEP OUT", { fontSize: 56, background: "#2c2118", border: "#b99154", color: "#d9bd84", subColor: "#9a7a4a" });
  TEX.ready = true;
  return TEX;
}

function std(color, options = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: options.roughness ?? 0.7,
    metalness: options.metalness ?? 0,
    emissive: options.emissive ?? 0x000000,
    emissiveIntensity: options.emissiveIntensity ?? 0,
    map: options.map ?? null,
    transparent: options.transparent ?? false,
    opacity: options.opacity ?? 1,
    side: options.side ?? THREE.FrontSide,
    flatShading: options.flatShading ?? false,
  });
}

function basic(color, options = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    map: options.map ?? null,
    transparent: options.transparent ?? false,
    opacity: options.opacity ?? 1,
    side: options.side ?? THREE.FrontSide,
    blending: options.blending ?? THREE.NormalBlending,
    depthWrite: options.depthWrite ?? true,
    fog: options.fog ?? true,
  });
}

function addBox(group, w, h, d, material, x = 0, y = 0, z = 0, cast = true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  mesh.position.set(x, y, z);
  mesh.castShadow = cast;
  mesh.receiveShadow = true;
  group.add(mesh);
  return mesh;
}

function addCyl(group, rt, rb, h, material, x = 0, y = 0, z = 0, seg = 16, cast = true) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), material);
  mesh.position.set(x, y, z);
  mesh.castShadow = cast;
  mesh.receiveShadow = true;
  group.add(mesh);
  return mesh;
}

function addPlane(group, w, h, material, x = 0, y = 0, z = 0, rotation = 0) {
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), material);
  mesh.position.set(x, y, z);
  mesh.rotation.y = rotation;
  mesh.receiveShadow = true;
  group.add(mesh);
  return mesh;
}

function addLamp(group, x, y, z, color = "#ffb45c", intensity = 12, distance = 8, scale = 1) {
  const fixture = new THREE.Group();
  const bracket = addBox(fixture, 0.04, 0.04, 0.34, std("#3d2b1d", { metalness: 0.55, roughness: 0.4 }), 0, 0.16, -0.13);
  bracket.rotation.x = 0.2;
  const cap = addCyl(fixture, 0.08, 0.11, 0.05, std("#4b3220", { metalness: 0.55, roughness: 0.34 }), 0, 0.25, 0.05, 12);
  const glass = addCyl(fixture, 0.075, 0.095, 0.22, std(color, {
    emissive: color,
    emissiveIntensity: 1.5,
    roughness: 0.22,
    transparent: true,
    opacity: 0.7,
  }), 0, 0.12, 0.05, 14);
  const base = addCyl(fixture, 0.09, 0.07, 0.05, std("#4b3220", { metalness: 0.55, roughness: 0.34 }), 0, 0, 0.05, 12);
  const flame = new THREE.Mesh(new THREE.SphereGeometry(0.035 * scale, 10, 8), basic(color));
  flame.position.set(0, 0.1, 0.05);
  flame.scale.y = 1.5;
  fixture.add(flame);

  fixture.position.set(x, y, z);
  fixture.scale.setScalar(scale);
  fixture.rotation.y = x < 0 ? 0.3 : -0.3;
  group.add(fixture);

  const light = new THREE.PointLight(color, intensity, distance, 1.7);
  light.position.set(x, y + 0.1 * scale, z + 0.05);
  light.castShadow = false;
  group.add(light);
  return { light, flame };
}

function addDust(group, count, bounds, color = "#f0c98e", size = 0.035, opacity = 0.5) {
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 3);
  const phases = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    positions[i * 3] = (Math.random() - 0.5) * bounds[0];
    positions[i * 3 + 1] = Math.random() * bounds[1];
    positions[i * 3 + 2] = (Math.random() - 0.5) * bounds[2];
    phases[i] = Math.random() * TAU;
  }
  geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geo.setAttribute("phase", new THREE.BufferAttribute(phases, 1));
  const material = new THREE.PointsMaterial({
    color,
    size,
    map: textures().dust,
    transparent: true,
    opacity,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    sizeAttenuation: true,
  });
  const points = new THREE.Points(geo, material);
  points.userData.base = positions.slice();
  points.userData.phases = phases;
  points.userData.animate = true;
  group.add(points);
  return points;
}

function addStars(group, count = 90) {
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.random() * Math.PI * 0.38;
    const radius = 38 + Math.random() * 10;
    positions[i * 3] = Math.cos(theta) * Math.sin(phi) * radius;
    positions[i * 3 + 1] = Math.cos(phi) * radius + 3;
    positions[i * 3 + 2] = Math.sin(theta) * Math.sin(phi) * radius;
  }
  geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  const mat = new THREE.PointsMaterial({
    color: "#f5e7c6",
    size: 0.13,
    map: textures().star,
    transparent: true,
    opacity: 0.75,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    sizeAttenuation: true,
  });
  const stars = new THREE.Points(geo, mat);
  group.add(stars);
  return stars;
}

function addSky(group, texture) {
  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(60, 32, 20),
    new THREE.MeshBasicMaterial({ map: texture, side: THREE.BackSide, fog: false })
  );
  sky.position.y = 4;
  group.add(sky);
  return sky;
}

function addSun(group, x, y, z, color = "#ffd79b", size = 5) {
  const sun = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: textures().star,
      color,
      transparent: true,
      opacity: 0.95,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      fog: false,
    })
  );
  sun.scale.set(size, size, 1);
  sun.position.set(x, y, z);
  group.add(sun);
  return sun;
}

function addMountains(group, color = "#352a27", z = -24, scale = 1) {
  const material = std(color, { roughness: 0.94, flatShading: true });
  for (let i = 0; i < 9; i++) {
    const width = (6 + Math.random() * 10) * scale;
    const height = (4 + Math.random() * 8) * scale;
    const peak = new THREE.Mesh(new THREE.ConeGeometry(width, height, 5), material);
    peak.position.set(-24 + i * 6 + (Math.random() - 0.5) * 3, height / 2 - 1.5, z - Math.random() * 6);
    peak.rotation.y = Math.random() * Math.PI;
    peak.scale.z = 0.6 + Math.random() * 0.5;
    group.add(peak);
  }
}

function addCactus(group, x, z, scale = 1, color = "#3f5338") {
  const mat = std(color, { roughness: 0.86, flatShading: true });
  const cactus = new THREE.Group();
  const trunk = addCyl(cactus, 0.11, 0.15, 2.2, mat, 0, 1.1, 0, 9);
  trunk.rotation.z = -0.02;
  const armGeo = new THREE.CylinderGeometry(0.07, 0.09, 0.85, 8);
  for (const side of [-1, 1]) {
    const arm = new THREE.Mesh(armGeo, mat);
    arm.position.set(side * 0.28, 1.35 + side * 0.07, 0);
    arm.rotation.z = side * 0.55;
    arm.castShadow = true;
    cactus.add(arm);
    const elbow = new THREE.Mesh(new THREE.SphereGeometry(0.085, 8, 6), mat);
    elbow.position.set(side * 0.17, 1.2, 0);
    elbow.castShadow = true;
    cactus.add(elbow);
    const up = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.075, 0.6, 8), mat);
    up.position.set(side * 0.42, 1.6, 0);
    up.rotation.z = side * 0.03;
    up.castShadow = true;
    cactus.add(up);
  }
  cactus.position.set(x, 0, z);
  cactus.scale.setScalar(scale);
  group.add(cactus);
}

function addBarrel(group, x, z, scale = 1, rotation = 0) {
  const mat = std("#5d3921", { roughness: 0.82, map: textures().wood });
  const barrel = addCyl(group, 0.28, 0.34, 0.78, mat, x, 0.39 * scale, z, 14);
  barrel.scale.setScalar(scale);
  barrel.rotation.y = rotation;
  const hoopMat = std("#2e231b", { metalness: 0.55, roughness: 0.5 });
  for (const y of [0.12, 0.66]) {
    const hoop = new THREE.Mesh(new THREE.TorusGeometry(0.31 * scale, 0.012 * scale, 5, 24), hoopMat);
    hoop.rotation.x = Math.PI / 2;
    hoop.position.set(x, y * scale, z);
    hoop.scale.z = scale;
    group.add(hoop);
  }
  return barrel;
}

function addCrate(group, x, y, z, size = 0.5, rotation = 0) {
  const crate = addBox(group, size, size, size, std("#695035", { roughness: 0.85, map: textures().woodDark }), x, y, z);
  crate.rotation.y = rotation;
  const trim = std("#3b2a1a", { roughness: 0.8 });
  for (const d of [-1, 1]) {
    addBox(group, size + 0.01, 0.035, 0.035, trim, x, y + d * size * 0.38, z + size / 2 + 0.01);
  }
  return crate;
}

function addWagonWheel(group, x, y, z, scale = 1) {
  const wheel = new THREE.Group();
  const wood = std("#5d4028", { roughness: 0.86, map: textures().wood });
  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.55, 0.06, 6, 22), wood);
  wheel.add(rim);
  const hub = addCyl(wheel, 0.1, 0.1, 0.24, std("#3b2717", { roughness: 0.8 }), 0, 0, 0, 10);
  hub.rotation.z = Math.PI / 2;
  for (let i = 0; i < 10; i++) {
    const spoke = addBox(wheel, 0.035, 1.06, 0.035, wood, 0, 0, 0);
    spoke.rotation.z = (i / 10) * Math.PI;
  }
  wheel.position.set(x, y, z);
  wheel.scale.setScalar(scale);
  wheel.rotation.y = 0.15;
  group.add(wheel);
  return wheel;
}

function addChair(group, x, z, rotation = 0, material = null) {
  const wood = material ?? std("#4a2d1b", { roughness: 0.82, map: textures().wood });
  const chair = new THREE.Group();
  addBox(chair, 0.44, 0.055, 0.44, wood, 0, 0.47, 0);
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      addBox(chair, 0.045, 0.46, 0.045, wood, sx * 0.18, 0.23, sz * 0.18);
    }
  }
  for (const sx of [-1, 1]) addBox(chair, 0.045, 0.48, 0.045, wood, sx * 0.18, 0.71, -0.19);
  addBox(chair, 0.42, 0.06, 0.04, wood, 0, 0.92, -0.19);
  chair.position.set(x, 0, z);
  chair.rotation.y = rotation;
  group.add(chair);
  return chair;
}

function addTable(group, x, z, scale = 1) {
  const wood = std("#51321e", { roughness: 0.8, map: textures().wood });
  const table = new THREE.Group();
  addBox(table, 1.0, 0.07, 0.85, wood, 0, 0.77, 0);
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) addBox(table, 0.06, 0.74, 0.06, wood, sx * 0.4, 0.37, sz * 0.33);
  }
  table.position.set(x, 0, z);
  table.scale.setScalar(scale);
  group.add(table);
  return table;
}

function addBottle(group, x, y, z, color = "#6f3d18", scale = 1) {
  const glass = std(color, {
    roughness: 0.22,
    metalness: 0.05,
    transparent: true,
    opacity: 0.72,
    emissive: color,
    emissiveIntensity: 0.12,
  });
  const bottle = new THREE.Group();
  addCyl(bottle, 0.045, 0.06, 0.22, glass, 0, 0.11, 0, 10);
  addCyl(bottle, 0.02, 0.035, 0.1, glass, 0, 0.27, 0, 8);
  addCyl(bottle, 0.022, 0.022, 0.035, std("#3a2418", { roughness: 0.5 }), 0, 0.34, 0, 8);
  bottle.position.set(x, y, z);
  bottle.scale.setScalar(scale);
  group.add(bottle);
  return bottle;
}

function addHorse(group, x, z, color = "#6a4630", rotation = 0) {
  const horse = new THREE.Group();
  const hide = std(color, { roughness: 0.82 });
  const dark = std("#2d1d16", { roughness: 0.9 });
  const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.32, 0.85, 8, 14), hide);
  body.rotation.z = Math.PI / 2;
  body.position.set(0, 1.18, 0);
  body.castShadow = true;
  horse.add(body);
  const chest = new THREE.Mesh(new THREE.SphereGeometry(0.34, 16, 12), hide);
  chest.scale.set(1, 1.15, 0.85);
  chest.position.set(0.55, 1.2, 0);
  horse.add(chest);
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.25, 0.85, 12), hide);
  neck.position.set(0.78, 1.55, 0);
  neck.rotation.z = -0.55;
  horse.add(neck);
  const head = new THREE.Mesh(new THREE.CapsuleGeometry(0.15, 0.33, 6, 10), hide);
  head.rotation.z = Math.PI / 2.5;
  head.position.set(1.02, 1.82, 0);
  horse.add(head);
  for (const s of [-1, 1]) {
    const ear = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.18, 7), hide);
    ear.position.set(0.94, 2.02, s * 0.1);
    ear.rotation.z = -0.2;
    horse.add(ear);
  }
  const mane = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.62, 0.05), dark);
  mane.position.set(0.65, 1.72, 0);
  mane.rotation.z = -0.55;
  horse.add(mane);
  const tail = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.7, 8), dark);
  tail.position.set(-0.82, 1.05, 0);
  tail.rotation.z = 0.25;
  horse.add(tail);
  for (const sx of [-0.5, 0.5]) {
    for (const sz of [-0.22, 0.22]) {
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.055, 1.05, 8), hide);
      leg.position.set(sx, 0.53, sz);
      leg.castShadow = true;
      horse.add(leg);
      const hoof = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.08, 0.12, 8), dark);
      hoof.position.set(sx, 0.06, sz);
      horse.add(hoof);
    }
  }
  const saddle = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.15, 0.48), std("#5f3821", { roughness: 0.78 }));
  saddle.position.set(0, 1.55, 0);
  horse.add(saddle);
  horse.position.set(x, 0, z);
  horse.rotation.y = rotation;
  group.add(horse);
  return horse;
}

function addPiano(group, x, z, rotation = 0) {
  const piano = new THREE.Group();
  const wood = std("#3c2217", { roughness: 0.62, map: textures().wood });
  addBox(piano, 1.65, 1.05, 0.72, wood, 0, 0.6, 0);
  addBox(piano, 1.72, 0.08, 0.82, wood, 0, 1.16, 0);
  addBox(piano, 1.5, 0.06, 0.2, std("#e5dcc5", { roughness: 0.3 }), 0, 0.94, 0.37);
  for (let i = 0; i < 20; i++) {
    const key = addBox(piano, 0.055, 0.025, 0.15, std(i % 7 === 0 ? "#21130f" : "#e9dfc7", { roughness: 0.35 }), -0.64 + i * 0.067, 0.975, 0.29);
    key.castShadow = false;
  }
  addBox(piano, 1.25, 0.08, 0.12, wood, 0, 0.7, 0.63);
  for (const sx of [-1, 1]) addBox(piano, 0.1, 0.6, 0.1, wood, sx * 0.58, 0.3, 0.32);
  piano.position.set(x, 0, z);
  piano.rotation.y = rotation;
  group.add(piano);
  return piano;
}

function addChandelier(group, x, y, z) {
  const metal = std("#7d5d2c", { metalness: 0.75, roughness: 0.38 });
  const hub = new THREE.Mesh(new THREE.SphereGeometry(0.16, 14, 10), metal);
  hub.position.set(x, y, z);
  group.add(hub);
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.72, 0.025, 6, 30), metal);
  ring.rotation.x = Math.PI / 2;
  ring.position.set(x, y - 0.1, z);
  group.add(ring);
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU;
    const cx = x + Math.cos(a) * 0.72;
    const cz = z + Math.sin(a) * 0.72;
    const spoke = addBox(group, 0.02, 0.02, 0.38, metal, x + Math.cos(a) * 0.38, y - 0.04, z + Math.sin(a) * 0.38);
    spoke.rotation.y = -a + Math.PI / 2;
    const candle = addCyl(group, 0.028, 0.028, 0.24, std("#e8dcc0", { roughness: 0.7 }), cx, y + 0.06, cz, 8);
    const flame = new THREE.Mesh(new THREE.SphereGeometry(0.028, 8, 6), basic("#ffd18b"));
    flame.scale.y = 1.7;
    flame.position.set(cx, y + 0.2, cz);
    group.add(flame);
    const light = new THREE.PointLight("#ffb15d", 5, 5, 1.8);
    light.position.set(cx, y + 0.2, cz);
    group.add(light);
  }
  const chain = addCyl(group, 0.012, 0.012, 1.1, metal, x, y + 0.6, z, 6);
  chain.castShadow = false;
}

function addWindowGlow(group, x, y, z, w, h, rotation = 0) {
  const frame = addBox(group, w + 0.16, h + 0.16, 0.08, std("#2a1a12", { roughness: 0.65 }), x, y, z - 0.03);
  const plane = addPlane(group, w, h, basic("#ffd08c", { map: textures().window, transparent: false }), x, y, z + 0.025);
  plane.rotation.y = rotation;
  if (rotation) frame.rotation.y = rotation;
  return plane;
}

function addDustAnimators(group) {
  const dusts = [];
  group.traverse((obj) => {
    if (obj.isPoints && obj.userData.animate) dusts.push(obj);
  });
  group.userData.dusts = dusts;
  group.userData.flames = [];
  group.traverse((obj) => {
    if (obj.material && obj.material.isMeshBasicMaterial && obj.material.color) {
      const c = obj.material.color;
      if (c.r > 0.8 && c.g > 0.6 && c.b < 0.65) group.userData.flames.push(obj);
    }
  });
}

function finalizeEnvironment(group, options = {}) {
  addDustAnimators(group);
  return {
    group,
    bg: options.bg ?? "#1a1210",
    fog: options.fog ?? { color: 0x1a1210, near: 10, far: 34 },
    camera: options.camera ?? { pos: new THREE.Vector3(0, 1.75, 5.2), target: new THREE.Vector3(0, 1.1, 0) },
    key: options.key ?? null,
    fill: options.fill ?? null,
    practicals: options.practicals ?? [],
    exposure: options.exposure ?? 1.05,
    titleCamera: options.titleCamera ?? null,
    fogDensity: options.fogDensity ?? null,
  };
}

