    addBox(stall, 2.2, 0.15, 0.15, std("#4c3120", { roughness: 0.86 }), -sx * 1.0, 2.45, 1.8);
    addBox(stall, 0.15, 1.1, 0.15, std("#4c3120", { roughness: 0.86 }), -sx * 1.9, 2.0, 1.8);
