  group.add(fill);

  // Ground
  const ground = addPlane(group, 36, 26, std("#75513a", { roughness: 0.98, map: t.dirt }), 0, 0, -4);
  ground.rotation.x = -Math.PI / 2;

  // Mine entrance
  const mine = new THREE.Group();
