  mineSign.material.emissiveIntensity = 0.11;
  group.add(mine);

  // Rocks around
  for (let i = 0; i < 14; i++) {
    const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(0.5 + Math.random() * 1.0, 0), rockMat);
    rock.position.set(-10 + Math.random() * 20, 0.2 + Math.random() * 0.3, -2 + Math.random() * 8);
    rock.rotation.set(Math.random(), Math.random(), Math.random());
    rock.scale.y = 0.5 + Math.random() * 0.6;
    rock.castShadow = true;
    rock.receiveShadow = true;
    group.add(rock);
  }

  // Mine cart and tracks
  const tracks = new THREE.Group();
  const railMat = std("#5a4a3c", { metalness: 0.75, roughness: 0.45 });
  for (const sx of [-0.65, 0.65]) {
    addBox(tracks, 0.08, 0.06, 10, railMat, sx, 0.07, 0);
    for (let i = 0; i < 9; i++) addBox(tracks, 0.12, 0.08, 0.12, std("#3a2b20", { roughness: 0.8 }), sx, 0.03, -4.4 + i * 1.1);
  }
  for (let i = 0; i < 18; i++) addBox(tracks, 1.65, 0.05, 0.16, std("#4a3424", { roughness: 0.8 }), 0, 0.04, -4.5 + i * 0.55);
  tracks.position.set(0, 0, 3.0);
  group.add(tracks);

  const cart = new THREE.Group();
  cart.position.set(1.4, 0.4, 2.9);
  addBox(cart, 1.4, 0.75, 1.0, std("#4b3323", { roughness: 0.78, map: t.wood }), 0, 0.38, 0);
  addBox(cart, 1.25, 0.08, 0.85, std("#2a1d15", { roughness: 0.8 }), 0, 0.71, 0);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.19, 0.19, 0.08, 12), std("#2c211a", { metalness: 0.6, roughness: 0.5 }));
    wheel.rotation.z = Math.PI / 2;
    wheel.position.set(sx * 0.55, -0.2, sz * 0.38);
    cart.add(wheel);
  }
  const ore = new THREE.Mesh(new THREE.DodecahedronGeometry(0.32, 0), std("#8f7d64", { roughness: 0.9, metalness: 0.25 }));
  ore.position.set(0, 0.82, 0);
  ore.scale.y = 0.6;
  cart.add(ore);
  group.add(cart);

  // Crates / powder
  addCrate(group, -3.6, 0.3, 2.3, 0.6, 0.2);
  addCrate(group, -3.2, 0.88, 2.3, 0.5, -0.1);
  const powder = addBox(group, 0.65, 0.55, 0.55, std("#6f4a25", { roughness: 0.86 }), 3.7, 0.3, 2.0);
  addBox(group, 0.52, 0.06, 0.52, std("#c6a35f", { roughness: 0.8 }), 3.7, 0.56, 2.0);
  addBox(group, 0.65, 0.05, 0.06, std("#2c1c11", { roughness: 0.8 }), 3.7, 0.3, 2.28);

  // Lanterns
  practicals.push(addLamp(group, -2.8, 3.2, 1.9, "#ffb45c", 20, 8, 1).light);
  practicals.push(addLamp(group, 2.8, 3.1, 1.7, "#ffb45c", 16, 8, 0.95).light);

  // warm glow inside mine
  const glow = new THREE.PointLight("#ff8f43", 22, 8, 1.6);
  glow.position.set(0, 2.1, -3.0);
  group.add(glow);
  practicals.push(glow);

  // cacti and scrub
  addCactus(group, -8.5, 3.0, 1.0, "#3b4a32");
  addCactus(group, 8.0, 4.0, 0.8, "#3a4830");

  addDust(group, 120, [18, 7, 12], "#f0c88d", 0.04, 0.42);
  const dust = group.children.find((c) => c.isPoints && c.userData.animate);

  const env = finalizeEnvironment(group, {
    bg: "#35272b",
    fog: { color: new THREE.Color("#5d4032"), near: 14, far: 38 },
    camera: { pos: new THREE.Vector3(0, 1.78, 5.5), target: new THREE.Vector3(0, 1.3, -0.8) },
    key: sunLight,
    fill,
    practicals,
    exposure: 1.08,
  });
  env.dust = dust;
  env.hemi = hemi;
  return env;
}

export function createEnvironment(name) {
  switch (name) {
    case "streetDusk":
      return createStreet("dusk");
    case "streetDawn":
      return createStreet("dawn");
    case "saloon":
      return createSaloon("night");
    case "saloonNight":
      return createSaloon("night");
    case "saloonDawn":
      return createSaloon("dawn");
    case "clinic":
      return createClinic("night");
    case "clinicDawn":
      return createClinic("dawn");
    case "stable":
      return createStable();
    case "mine":
      return createMine();
    default:
      return createSaloon("night");
  }
}

export function animateEnvironment(env, time) {
  if (!env) return;
  if (env.dust) {
    const pos = env.dust.geometry.attributes.position;
    const base = env.dust.userData.base;
    const phases = env.dust.userData.phases;
    for (let i = 0; i < pos.count; i++) {
      const phase = phases[i];
      pos.array[i * 3] = base[i * 3] + Math.sin(time * 0.13 + phase) * 0.45;
      pos.array[i * 3 + 1] = base[i * 3 + 1] + Math.sin(time * 0.22 + phase * 1.7) * 0.28;
      pos.array[i * 3 + 2] = base[i * 3 + 2] + Math.cos(time * 0.11 + phase) * 0.35;
    }
    pos.needsUpdate = true;
  }
  if (env.tumble) {
    env.tumble.rotation.x = time * 0.22;
    env.tumble.rotation.z = time * 0.17;
    env.tumble.position.x = -2.2 + Math.sin(time * 0.06) * 3.4;
    env.tumble.position.z = 3.2 + Math.cos(time * 0.05) * 0.8;
    env.tumble.position.y = 0.32 + Math.abs(Math.sin(time * 0.9)) * 0.08;
  }
  if (env.group.userData.flames) {
    env.group.userData.flames.forEach((flame, i) => {
      const flicker = 0.85 + Math.sin(time * 11 + i * 2.3) * 0.15 + Math.sin(time * 17 + i) * 0.08;
      flame.scale.set(flicker, 1.5 + flicker * 0.3, flicker);
      if (flame.material) flame.material.opacity = 0.8 + flicker * 0.2;
    });
  }
  if (env.practicals) {
    env.practicals.forEach((light, i) => {
      if (!light.isLight) return;
      const base = light.userData.baseIntensity ?? (light.userData.baseIntensity = light.intensity);
      light.intensity = base * (0.94 + Math.sin(time * 8.4 + i * 1.9) * 0.035 + Math.sin(time * 13.7 + i) * 0.025);
    });
  }
}

import * as THREE from "three";
import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
import { OutputPass } from "three/addons/postprocessing/OutputPass.js";
import { createCharacter } from "./characters.js";
import { createEnvironment, animateEnvironment } from "./environments.js";

const CHARACTER_ORDER = ["clem", "ada", "rosa"];

export class World {
  constructor(canvas) {
    this.canvas = canvas;
    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: false,
      powerPreference: "high-performance",
      stencil: false,
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.65));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color("#140d0b");
    this.scene.fog = new THREE.Fog(0x140d0b, 12, 32);

    this.camera = new THREE.PerspectiveCamera(42, window.innerWidth / window.innerHeight, 0.1, 80);
    this.camera.position.set(0, 1.8, 5.6);

    this.composer = new EffectComposer(this.renderer);
    this.renderPass = new RenderPass(this.scene, this.camera);
    this.composer.addPass(this.renderPass);
    this.bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      0.42,
      0.58,
      0.82
    );
    this.composer.addPass(this.bloomPass);
    this.outputPass = new OutputPass();
    this.composer.addPass(this.outputPass);

    this.clock = new THREE.Clock();
    this.time = 0;
    this.elapsed = 0;
    this.environments = new Map();
    this.currentEnvironment = null;
    this.currentLocation = null;
    this.characters = new Map();
    this.cast = [];
    this.speaker = null;
    this.mood = "neutral";
    this.framing = "wide";
    this.pointer = new THREE.Vector2();
    this.pointerTarget = new THREE.Vector2();
    this.cameraPos = new THREE.Vector3(0, 1.8, 5.6);
    this.cameraTarget = new THREE.Vector3(0, 1.15, 0);
    this.desiredPos = new THREE.Vector3(0, 1.8, 5.6);
    this.desiredTarget = new THREE.Vector3(0, 1.15, 0);
    this.cameraDrift = 0;
    this.titleMode = false;
    this.endingPick = null;

    for (const id of CHARACTER_ORDER) {
      const character = createCharacter(id);
      character.visible = false;
      this.scene.add(character);
      this.characters.set(id, character);
    }

    // Soft front fill that follows the speaking character.
    this.characterFill = new THREE.PointLight("#ffd2a0", 7, 4.2, 1.8);
    this.characterFill.position.set(0, 1.6, 1.4);
    this.scene.add(this.characterFill);

    this.raycaster = new THREE.Raycaster();
    this.bindEvents();
    this.resize();
    this.preload();
    this.loop = this.loop.bind(this);
    this.renderer.setAnimationLoop(this.loop);
  }

  bindEvents() {
    this.onResize = () => this.resize();
    window.addEventListener("resize", this.onResize);
    this.onPointer = (event) => {
      const x = (event.clientX / window.innerWidth) * 2 - 1;
      const y = (event.clientY / window.innerHeight) * 2 - 1;
      this.pointerTarget.set(x, y);
    };
    window.addEventListener("pointermove", this.onPointer, { passive: true });
  }

  preload() {
    // Build the title environment immediately. Other sets are built on demand.
    this.ensureEnvironment("streetDusk");
  }

  ensureEnvironment(location) {
    if (this.environments.has(location)) return this.environments.get(location);
    const env = createEnvironment(location);
    env.group.visible = false;
    this.scene.add(env.group);
    this.environments.set(location, env);
    return env;
  }

  setLocation(location) {
    if (this.currentLocation === location) return;
    const env = this.ensureEnvironment(location);
    if (this.currentEnvironment) this.currentEnvironment.group.visible = false;
    env.group.visible = true;
    this.currentEnvironment = env;
    this.currentLocation = location;
    this.scene.background = new THREE.Color(env.bg);
    this.scene.fog = new THREE.Fog(env.fog.color ?? env.bg, env.fog.near ?? 10, env.fog.far ?? 34);
    this.renderer.toneMappingExposure = env.exposure ?? 1.05;
    this.currentEnvironment.group.updateMatrixWorld();
    this.updateCamera(true);
  }

  setCharacters(cast, speaker = null, mood = "neutral") {
    this.cast = [...cast];
    this.speaker = speaker;
    this.mood = mood;
    const portrait = window.innerWidth / window.innerHeight < 0.78;
    const count = cast.length;

    let xs = [0];
    let zs = [0.35];
    if (count === 2) {
      xs = [-0.72, 0.72];
      zs = [0.38, 0.38];
    } else if (count >= 3) {
      xs = portrait ? [-0.9, 0.05, 0.92] : [-1.45, 0.03, 1.48];
      zs = portrait ? [0.55, 0.18, 0.58] : [0.55, 0.3, 0.55];
    }

    CHARACTER_ORDER.forEach((id, index) => {
      const character = this.characters.get(id);
      const castIndex = cast.indexOf(id);
      if (castIndex === -1) {
        character.visible = false;
        return;
      }
      character.visible = true;
      let x = xs[castIndex] ?? 0;
      let z = zs[castIndex] ?? 0.35;
      if (count === 3 && portrait) {
        // keep protagonist-ish center character forward
        if (castIndex === 1) z = 0.1;
      }
      character.position.set(x, 0, z);
      let rot = 0;
      if (count >= 2) {
        rot = x < -0.2 ? 0.13 : x > 0.2 ? -0.13 : 0;
      }
      character.rotation.y = rot;
      const characterMood = id === speaker ? mood : "neutral";
      character.userData.setMood(characterMood);
      character.userData.setSpeaking(false);
      character.userData.targetVisible = true;
      character.userData.baseX = x;
    });

    if (speaker && this.characters.has(speaker)) {
      const char = this.characters.get(speaker);
      this.characterFill.position.set(char.position.x, 1.55, char.position.z + 1.5);
      this.characterFill.intensity = 6;
    } else {
      this.characterFill.intensity = 2.5;
    }
    this.updateCamera(true);
  }

  setSpeaking(id, speaking) {
    for (const [charId, character] of this.characters) {
      if (character.visible) character.userData.setSpeaking(charId === id && speaking);
    }
  }

  setMood(mood) {
    this.mood = mood;
    if (this.speaker && this.characters.has(this.speaker)) {
      this.characters.get(this.speaker).userData.setMood(mood);
    }
  }

  setTitle() {
    this.titleMode = true;
    this.endingPick = null;
    this.setLocation("streetDusk");
    this.setCharacters(["clem", "ada", "rosa"], null, "neutral");
    const clem = this.characters.get("clem");
    const ada = this.characters.get("ada");
    const rosa = this.characters.get("rosa");
    clem.userData.setMood("sly, confident");
    ada.userData.setMood("clinical, watching");
    rosa.userData.setMood("delight, dangerous");
    this.titleBase = {
      pos: new THREE.Vector3(0, 1.62, 5.2),
      target: new THREE.Vector3(0, 1.12, 0),
    };
    this.updateCamera(true);
  }

  setGameScene(location, cast, speaker, mood, framing = "wide") {
    this.titleMode = false;
    this.framing = framing;
    this.setLocation(location);
    this.setCharacters(cast, speaker, mood);
  }

  setEndingScene(location, cast, pick) {
    this.titleMode = false;
    this.endingPick = pick;
    this.setLocation(location);
    this.setCharacters(cast, null, "neutral");
    if (pick === "clem") {
      this.characters.get("clem")?.userData.setMood("soft, possessive");
    } else if (pick === "ada") {
      this.characters.get("ada")?.userData.setMood("clinical, possessive");
    } else if (pick === "rosa") {
      this.characters.get("rosa")?.userData.setMood("sly, possessive");
    } else if (pick === "all") {
      this.characters.get("clem")?.userData.setMood("soft, sly");
      this.characters.get("ada")?.userData.setMood("quiet, warm");
      this.characters.get("rosa")?.userData.setMood("delight");
    }
    this.updateCamera(true);
  }

  updateCamera(instant = false) {
    const env = this.currentEnvironment;
    if (!env) return;
    const aspect = window.innerWidth / window.innerHeight;
    const portrait = aspect < 0.78;
    const count = this.cast.length;
    let basePos = env.camera.pos.clone();
    let target = env.camera.target.clone();

    if (this.titleMode && this.titleBase) {
      basePos.copy(this.titleBase.pos);
      target.copy(this.titleBase.target);
    } else if (count >= 3) {
      basePos.z += portrait ? 1.7 : 1.15;
      target.y = 1.13;
      if (portrait) {
        basePos.y = 1.55;
      }
    } else if (count === 2) {
      basePos.z += 0.45;
      target.y = 1.12;
    } else if (count === 1) {
      target.y = 1.13;
      if (portrait) {
        basePos.z += 0.35;
        basePos.y = 1.55;
      }
    }

    this.camera.fov = portrait ? (count >= 3 ? 54 : 50) : count >= 3 ? 43 : 40;
    this.camera.aspect = aspect;
    this.camera.updateProjectionMatrix();

    if (instant) {
      this.cameraPos.copy(basePos);
      this.cameraTarget.copy(target);
      this.desiredPos.copy(basePos);
      this.desiredTarget.copy(target);
      this.camera.position.copy(basePos);
      this.camera.lookAt(target);
    }
    this.desiredPos.copy(basePos);
    this.desiredTarget.copy(target);
  }

  resize() {
    const width = window.innerWidth;
    const height = window.innerHeight;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, width < 700 ? 1.5 : 1.65));
    this.renderer.setSize(width, height);
    this.composer.setSize(width, height);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.updateCamera(true);
  }

  loop() {
    const dt = Math.min(this.clock.getDelta(), 0.05);
    this.elapsed += dt;
    const t = this.elapsed;

    // Ease pointer for a subtle camera parallax.
    this.pointer.lerp(this.pointerTarget, 1 - Math.exp(-dt * 1.8));

    const parallaxX = this.pointer.x * (this.camera.aspect < 0.78 ? 0.05 : 0.14);
    const parallaxY = this.pointer.y * 0.06;
    const driftX = Math.sin(t * 0.13) * 0.028;
    const driftY = Math.sin(t * 0.19) * 0.018;

    const targetPos = this.desiredPos.clone();
    targetPos.x += parallaxX + driftX;
    targetPos.y += -parallaxY + driftY;
    const targetLook = this.desiredTarget.clone();
    targetLook.x += parallaxX * 0.45;
    targetLook.y += -parallaxY * 0.2;

    if (this.titleMode) {
      targetPos.x += Math.sin(t * 0.07) * 0.18;
      targetPos.y += Math.sin(t * 0.11) * 0.035;
      targetLook.x += Math.sin(t * 0.07) * 0.06;
    }

    const smoothing = 1 - Math.exp(-dt * 3.2);
    this.cameraPos.lerp(targetPos, smoothing);
    this.cameraTarget.lerp(targetLook, smoothing);
    this.camera.position.copy(this.cameraPos);
    this.camera.lookAt(this.cameraTarget);

    // Characters breathe, sway, blink, and react.
    for (const [id, character] of this.characters) {
      if (!character.visible) continue;
      character.userData.update(t, dt);
      if (character.userData.speaking) {
        this.characterFill.position.x += (character.position.x - this.characterFill.position.x) * 0.1;
        this.characterFill.position.z += (character.position.z + 1.5 - this.characterFill.position.z) * 0.1;
      }
    }

    if (this.currentEnvironment) animateEnvironment(this.currentEnvironment, t);

    this.composer.render();
  }

  dispose() {
    window.removeEventListener("resize", this.onResize);
    window.removeEventListener("pointermove", this.onPointer);
    this.renderer.setAnimationLoop(null);
    this.composer.dispose?.();
    this.renderer.dispose();
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.started = false;
    this.muted = false;
    this.volume = 0.45;
    this.scene = "title";
    this.timer = null;
    this.noteIndex = 0;
    this.padNodes = [];
    this.master = null;
    this.ambient = null;
    this.delay = null;
  }

  init() {
    if (this.ctx) return;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : this.volume;
    this.master.connect(this.ctx.destination);

    this.ambient = this.ctx.createGain();
    this.ambient.gain.value = 0.7;
    this.ambient.connect(this.master);

    this.delay = this.ctx.createDelay(1.0);
    this.delay.delayTime.value = 0.42;
    const feedback = this.ctx.createGain();
    feedback.gain.value = 0.24;
    this.delay.connect(feedback);
    feedback.connect(this.delay);
    const wet = this.ctx.createGain();
    wet.gain.value = 0.3;
    this.delay.connect(wet);
    wet.connect(this.master);

    this.createWind();
    this.createPad();
  }

  createWind() {
    const ctx = this.ctx;
    const bufferSize = ctx.sampleRate * 4;
    const buffer = ctx.createBuffer(2, bufferSize, ctx.sampleRate);
    for (let channel = 0; channel < 2; channel++) {
      const data = buffer.getChannelData(channel);
      let last = 0;
      for (let i = 0; i < bufferSize; i++) {
        const white = Math.random() * 2 - 1;
        last = (last + 0.02 * white) / 1.02;
        data[i] = last * 3.2;
      }
    }
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = "bandpass";
    filter.frequency.value = 420;
    filter.Q.value = 0.65;
    const gain = ctx.createGain();
    gain.gain.value = 0.035;
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.ambient);
    source.start();
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.055;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 160;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    lfo.start();
    this.wind = { gain, filter };
  }

  chordFor(scene) {
    if (scene === "clinic" || scene === "clinicDawn") return [146.83, 174.61, 220.0, 261.63];
    if (scene === "mine") return [130.81, 155.56, 196.0, 246.94];
    if (scene === "stable") return [164.81, 196.0, 246.94, 293.66];
    if (scene === "streetDawn") return [174.61, 220.0, 261.63, 329.63];
    return [146.83, 185.0, 220.0, 293.66];
  }

  createPad() {
    const ctx = this.ctx;
    const chord = this.chordFor(this.scene);
    this.padNodes = chord.map((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = i % 2 ? "sine" : "triangle";
      osc.frequency.value = freq / (i === 0 ? 2 : 1);
      osc.detune.value = (i - 1.5) * 3.5;
      const gain = ctx.createGain();
      gain.gain.value = i === 0 ? 0.014 : 0.008;
      const filter = ctx.createBiquadFilter();
      filter.type = "lowpass";
      filter.frequency.value = 700;
      osc.connect(filter);
      filter.connect(gain);
      gain.connect(this.ambient);
      osc.start();
      return { osc, gain, filter };
    });
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.045;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 120;
    lfo.connect(lfoGain);
    lfoGain.connect(this.padNodes[0].filter.frequency);
    lfo.start();
    this.padLfo = lfo;
  }

  setScene(scene) {
    this.scene = scene;
    if (!this.ctx) return;
    const chord = this.chordFor(scene);
    const now = this.ctx.currentTime;
    this.padNodes.forEach((node, i) => {
      node.osc.frequency.cancelScheduledValues(now);
      node.osc.frequency.linearRampToValueAtTime(chord[i] / (i === 0 ? 2 : 1), now + 2.2);
    });
    if (this.wind) {
      const target = scene === "mine" ? 550 : scene.startsWith("street") ? 460 : 300;
      this.wind.filter.frequency.linearRampToValueAtTime(target, now + 2);
    }
  }

  start() {
    this.init();
    if (!this.ctx) return;
    if (this.ctx.state === "suspended") this.ctx.resume();
    if (this.started) return;
    this.started = true;
    this.schedulePluck(1.8);
  }

  schedulePluck(delay = 2.4) {
    if (!this.ctx) return;
    clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      if (!this.muted && this.ctx?.state === "running") this.pluck();
      this.schedulePluck(2.1 + Math.random() * 3.8);
    }, delay * 1000);
  }

  pluck() {
    const ctx = this.ctx;
    if (!ctx) return;
    const scales = {
      title: [293.66, 349.23, 440.0, 523.25, 587.33],
      streetDusk: [293.66, 349.23, 440.0, 523.25, 587.33],
      streetDawn: [349.23, 440.0, 523.25, 659.25, 698.46],
      saloon: [293.66, 349.23, 440.0, 523.25, 587.33],
      saloonNight: [293.66, 349.23, 440.0, 523.25, 587.33],
      saloonDawn: [349.23, 440.0, 523.25, 587.33, 698.46],
      clinic: [440.0, 523.25, 659.25, 783.99, 880.0],
      clinicDawn: [440.0, 523.25, 659.25, 783.99, 880.0],
      stable: [392.0, 440.0, 523.25, 587.33, 659.25],
      mine: [261.63, 311.13, 392.0, 466.16, 523.25],
    };
    const scale = scales[this.scene] ?? scales.title;
    this.noteIndex = (this.noteIndex + 1 + Math.floor(Math.random() * 2)) % scale.length;
    const freq = scale[this.noteIndex];
    const now = ctx.currentTime;

    const osc = ctx.createOscillator();
    osc.type = "triangle";
    osc.frequency.value = freq;
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.setValueAtTime(2500, now);
    filter.frequency.exponentialRampToValueAtTime(500, now + 0.8);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.055, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.4);
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    gain.connect(this.delay);
    osc.start(now);
    osc.stop(now + 1.6);

    // faint octave shimmer
    const shimmer = ctx.createOscillator();
    shimmer.type = "sine";
    shimmer.frequency.value = freq * 2;
    const sg = ctx.createGain();
    sg.gain.setValueAtTime(0.0001, now);
    sg.gain.exponentialRampToValueAtTime(0.009, now + 0.02);
    sg.gain.exponentialRampToValueAtTime(0.0001, now + 0.65);
    shimmer.connect(sg);
    sg.connect(this.delay);
    shimmer.start(now);
    shimmer.stop(now + 0.8);
  }

  setVolume(value) {
    this.volume = Math.max(0, Math.min(1, value));
    if (this.master && !this.muted) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(this.volume, this.ctx.currentTime + 0.1);
    }
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.master) return;
    this.master.gain.cancelScheduledValues(this.ctx.currentTime);
    this.master.gain.linearRampToValueAtTime(muted ? 0 : this.volume, this.ctx.currentTime + 0.25);
  }

  tone(freq = 440, duration = 0.12, type = "sine", gainValue = 0.04) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.value = freq;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(gainValue, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(now);
    osc.stop(now + duration + 0.03);
  }

  click() {
    this.tone(620, 0.055, "triangle", 0.035);
    setTimeout(() => this.tone(880, 0.04, "sine", 0.018), 25);
  }

  choice() {
    this.tone(392, 0.08, "triangle", 0.04);
    setTimeout(() => this.tone(587.33, 0.14, "sine", 0.03), 70);
  }

  heart() {
    this.tone(523.25, 0.18, "sine", 0.035);
    setTimeout(() => this.tone(659.25, 0.26, "sine", 0.026), 90);
  }

  obsession() {
    this.tone(220, 0.34, "sawtooth", 0.012);
    this.tone(233.08, 0.28, "sine", 0.018);
  }

  clue() {
    this.tone(880, 0.09, "sine", 0.022);
    setTimeout(() => this.tone(1174.66, 0.16, "sine", 0.018), 80);
  }

  transition() {
    this.tone(130.81, 0.8, "sine", 0.022);
    this.tone(196.0, 1.1, "triangle", 0.012);
  }

  ending() {
    const notes = [261.63, 329.63, 392.0, 523.25];
    notes.forEach((freq, i) => {
      setTimeout(() => this.tone(freq, 1.8, "sine", 0.028), i * 180);
    });
  }
}

